#include <cstdio>
#include <vector>

struct Node {
    int val;
    Node* next;
    Node(int v) : val(v), next(nullptr) {}
};

Node* build(const std::vector<int>& v) {
    Node dummy(0);
    Node* tail = &dummy;
    for (int x : v) { tail->next = new Node(x); tail = tail->next; }
    return dummy.next;
}

int main() {
    int n, m;
    scanf("%d %d", &n, &m);
    std::vector<int> a(n), b(m);
    for (int i = 0; i < n; ++i) scanf("%d", &a[i]);
    for (int i = 0; i < m; ++i) scanf("%d", &b[i]);

    Node* la = build(a);
    Node* lb = build(b);

    Node dummy(0);
    Node* tail = &dummy;
    while (la && lb) {
        if (la->val <= lb->val) { tail->next = la; la = la->next; }
        else { tail->next = lb; lb = lb->next; }
        tail = tail->next;
    }
    tail->next = la ? la : lb;

    bool first = true;
    for (Node* p = dummy.next; p; p = p->next) {
        if (!first) printf(" ");
        printf("%d", p->val);
        first = false;
    }
    printf("\n");
    return 0;
}
